<script lang="ts">import{rowSelectionFeature}from'@fex/components-core/data-grid/features/row-selection';import{DataGrid,tableFeatures,type Cell,type Header}from'@fex/components-svelte/primitive/data-grid';import type{TransferPanelApi}from'@fex/components-svelte/primitive/transfer';import{createDataGridTable}from'@fex/components-svelte/stores/create-data-grid-table';import Checkbox from'@fex/components-svelte/ui/checkbox';import type{Member}from'./data';let{api}:{api:TransferPanelApi<Member>}=$props();const features=tableFeatures({rowSelectionFeature});const columns=[{id:'__select__',header:'',size:44},{accessorKey:'name',header:'Name'},{accessorKey:'department',header:'Department'}];const options=()=>({features,data:[...api.items],columns,getRowId:(row:Member)=>row.id,enableRowSelection:(row:any)=>row.original.disabled!==true,state:{rowSelection:Object.fromEntries(api.checkedKeys.map(key=>[String(key),true]))},onRowSelectionChange:(updater:any)=>{const current=Object.fromEntries(api.checkedKeys.map(key=>[String(key),true]));const next=typeof updater==='function'?updater(current):updater;api.setCheckedKeys(Object.keys(next).filter(key=>next[key]))}});const table=createDataGridTable(options()as any);$effect(()=>table.setDataGridOptions(options()as any))</script>
{#snippet header(item:Header<any,Member>)}{#if item.column.id==='__select__'}<Checkbox checked={item.table.getIsAllRowsSelected()?true:item.table.getIsSomeRowsSelected()?'indeterminate':false} onCheckedChange={checked=>item.table.toggleAllRowsSelected(checked===true)}/>{:else}{String(item.column.columnDef.header??'')}{/if}{/snippet}{#snippet cell(item:Cell<any,Member>)}{#if item.column.id==='__select__'}<Checkbox checked={item.row.getIsSelected()} disabled={!item.row.getCanSelect()} onCheckedChange={checked=>item.row.toggleSelected(checked===true)}/>{:else}{String(item.getValue()??'')}{/if}{/snippet}<DataGrid {table} {header} {cell}/>
